#include <iostream>
#include <string>
#include <cstdio>
#include <cmath>
// Print many candidate variants for one triple, each as "y u v" with the SAME ostream stmt.
int main(int argc,char**argv){
  float r=0.4f,g=0.2f,b=0.8f;
  if(argc>3){r=std::stof(argv[1]);g=std::stof(argv[2]);b=std::stof(argv[3]);}
  double R=r,G=g,B=b;
  struct Row{const char*n;float y,u,v;};
  Row rows[]={
   // 0: claimed all-float left-to-right
   {"F_LTR", (float)(((0.299f*r)+(0.587f*g))+(0.114f*b)),
             (float)(((-0.147f*r)-(0.289f*g))+(0.436f*b)),
             (float)(((0.615f*r)-(0.515f*g))-(0.100f*b))},
   // 1: all double constants + double accumulation, store to float
   {"D_LTR", (float)(((0.299*R)+(0.587*G))+(0.114*B)),
             (float)(((-0.147*R)-(0.289*G))+(0.436*B)),
             (float)(((0.615*R)-(0.515*G))-(0.100*B))},
   // 2: right-assoc float
   {"F_RTL", (float)((0.299f*r)+((0.587f*g)+(0.114f*b))),
             (float)((-0.147f*r)-((0.289f*g)-(0.436f*b))),
             (float)((0.615f*r)-((0.515f*g)+(0.100f*b)))},
   // 3: u alternative: b-term first
   {"U_BFIRST", (float)(((0.114f*b)+(0.299f*r))+(0.587f*g)),
             (float)(((0.436f*b)-(0.147f*r))-(0.289f*g)),
             (float)(((0.615f*r)-(0.100f*b))-(0.515f*g))},
   // 4: mixed: one double constant (0.587 double) -> whole y becomes double
   {"MIX587", (float)(((0.299f*r)+(0.587*G))+(0.114f*b)),
             (float)(((-0.147f*r)-(0.289*G))+(0.436f*b)),
             (float)(((0.615f*r)-(0.515*G))-(0.100f*b))},
   // 5: mixed: only first constant double
   {"MIX1st", (float)(((0.299*R)+(0.587f*g))+(0.114f*b)),
             (float)(((-0.147*R)-(0.289f*g))+(0.436f*b)),
             (float)(((0.615*R)-(0.515f*g))-(0.100f*b))},
   // 6: mixed: only last constant double
   {"MIXlast",(float)(((0.299f*r)+(0.587f*g))+(0.114*B)),
             (float)(((-0.147f*r)-(0.289f*g))+(0.436*B)),
             (float)(((0.615f*r)-(0.515f*g))-(0.100*B))},
   // 7: float ops but each product rounded via double mult of float-consts (same as F_LTR) - control
   {"NEGFOLD",(float)(((0.299f*r)+(0.587f*g))+(0.114f*b)),
             (float)((((-0.147f)*r)+((-0.289f)*g))+(0.436f*b)),
             (float)(((0.615f*r)+((-0.515f)*g))+((-0.100f)*b))},
   // 8: FMA-contracted (explicit fmaf), left-to-right
   {"FMA",   (float)fmaf(0.114f,b,fmaf(0.587f,g,0.299f*r)),
             (float)fmaf(0.436f,b,fmaf(-0.289f,g,-0.147f*r)),
             (float)fmaf(-0.100f,b,fmaf(-0.515f,g,0.615f*r))},
   // 9: constants at double, but FIELD double -> print more digits (simulate double field)
   {"DFIELD",0,0,0},
  };
  for(int i=0;i<9;i++) std::cout<<rows[i].n<<" "<<rows[i].y<<" "<<rows[i].u<<" "<<rows[i].v<<"\n";
  double dy=((0.299*R)+(0.587*G))+(0.114*B), du=((-0.147*R)-(0.289*G))+(0.436*B), dv=((0.615*R)-(0.515*G))-(0.100*B);
  std::cout<<"DFIELD "<<dy<<" "<<du<<" "<<dv<<"\n";
  double fy=((0.299f*R)+(0.587f*G))+(0.114f*B), fu=((-0.147f*R)-(0.289f*G))+(0.436f*B), fv=((0.615f*R)-(0.515f*G))-(0.100f*B);
  std::cout<<"DFIELD_FC "<<fy<<" "<<fu<<" "<<fv<<"\n";
  return 0;
}
