#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <cstdint>
#include <string>
#include <vector>
#include <random>
static inline float F(uint32_t u){float f;memcpy(&f,&u,4);return f;}
struct V{float y,u,v;};
// variant generators
static V v_ltr(float r,float g,float b){return {((0.299f*r)+(0.587f*g))+(0.114f*b),((-0.147f*r)-(0.289f*g))+(0.436f*b),((0.615f*r)-(0.515f*g))-(0.100f*b)};}
static V v_rtl(float r,float g,float b){return {(0.299f*r)+((0.587f*g)+(0.114f*b)),(-0.147f*r)-((0.289f*g)-(0.436f*b)),(0.615f*r)-((0.515f*g)+(0.100f*b))};}
static V v_mid(float r,float g,float b){return {((0.299f*r)+(0.114f*b))+(0.587f*g),((-0.147f*r)+(0.436f*b))-(0.289f*g),((0.615f*r)-(0.100f*b))-(0.515f*g)};}
static V v_bf (float r,float g,float b){return {((0.114f*b)+(0.587f*g))+(0.299f*r),((0.436f*b)-(0.147f*r))-(0.289f*g),((-0.100f*b)+(0.615f*r))-(0.515f*g)};}
static V v_fma(float r,float g,float b){return {fmaf(0.114f,b,fmaf(0.587f,g,0.299f*r)),fmaf(0.436f,b,fmaf(-0.289f,g,-0.147f*r)),fmaf(-0.100f,b,fmaf(-0.515f,g,0.615f*r))};}
// fma only on last op (typical gcc contraction of a*x+b*y+c*z left-to-right: t=a*x; t=fma(b,y,t)? actually gcc does t=a*x+b*y then fma(c,z,t))
static V v_fma1(float r,float g,float b){return {fmaf(0.114f,b,(0.299f*r)+(0.587f*g)),fmaf(0.436f,b,(-0.147f*r)-(0.289f*g)),fmaf(-0.100f,b,(0.615f*r)-(0.515f*g))};}
static V v_dbl(float r,float g,float b){double R=r,G=g,B=b;return {(float)(((0.299*R)+(0.587*G))+(0.114*B)),(float)(((-0.147*R)-(0.289*G))+(0.436*B)),(float)(((0.615*R)-(0.515*G))-(0.100*B))};}
struct Cand{const char*n;V(*f)(float,float,float);};
static Cand cands[]={{"LTR",v_ltr},{"RTL",v_rtl},{"MID",v_mid},{"BF",v_bf},{"FMA",v_fma},{"FMA1",v_fma1},{"DBL",v_dbl}};
static const int NC=sizeof(cands)/sizeof(cands[0]);
static bool same(float a,float b){uint32_t x,y;memcpy(&x,&a,4);memcpy(&y,&b,4);return x==y;}
int main(int argc,char**argv){
  int mode=atoi(argv[1]); // 0 = find discriminators
  std::mt19937_64 rng(atoi(argv[2]));
  int want=atoi(argv[3]);
  int found=0;
  // pool of "interesting" magnitudes
  while(found<want){
    float t[3];
    for(int k=0;k<3;k++){
      int m=rng()%5;
      double x;
      if(m==0) x=(double)(rng()%1000000)/1000000.0;
      else if(m==1) x=(double)(rng()%256)/256.0;
      else if(m==2) x=ldexp((double)(rng()%(1<<23)),-23)*ldexp(1.0,(int)(rng()%20)-10);
      else if(m==3) x=(double)(rng()%2000000)/1000.0-1000.0;
      else x=(double)(int64_t)(rng()%2000)-1000.0;
      t[k]=(float)x;
    }
    // does any pair of candidates differ?
    V res[NC]; for(int i=0;i<NC;i++) res[i]=cands[i].f(t[0],t[1],t[2]);
    bool diff=false;
    for(int i=1;i<NC;i++) if(!same(res[i].y,res[0].y)||!same(res[i].u,res[0].u)||!same(res[i].v,res[0].v)) diff=true;
    if(!diff) continue;
    // require the difference to be visible at 6 sig digits for at least one field
    char buf[NC][3][64]; bool vis=false;
    for(int i=0;i<NC;i++){snprintf(buf[i][0],64,"%.6g",(double)res[i].y);snprintf(buf[i][1],64,"%.6g",(double)res[i].u);snprintf(buf[i][2],64,"%.6g",(double)res[i].v);}
    for(int i=1;i<NC;i++)for(int k=0;k<3;k++) if(strcmp(buf[i][k],buf[0][k])) vis=true;
    if(!vis) continue;
    printf("%.9g %.9g %.9g |",t[0],t[1],t[2]);
    for(int i=0;i<NC;i++) printf(" %s=%s,%s,%s",cands[i].n,buf[i][0],buf[i][1],buf[i][2]);
    printf("\n");
    found++;
  }
  return 0;
}
