// generate corpus of triples as %.9g decimal strings (stof-exact, no subnormal/overflow)
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <cstdint>
#include <random>
#include <set>
#include <string>
static inline float FB(uint32_t u){float f;memcpy(&f,&u,4);return f;}
struct V{float y,u,v;};
static V v_ltr(float r,float g,float b){return {((0.299f*r)+(0.587f*g))+(0.114f*b),((-0.147f*r)-(0.289f*g))+(0.436f*b),((0.615f*r)-(0.515f*g))-(0.100f*b)};}
static V v_rtl(float r,float g,float b){return {(0.299f*r)+((0.587f*g)+(0.114f*b)),(-0.147f*r)-((0.289f*g)-(0.436f*b)),(0.615f*r)-((0.515f*g)+(0.100f*b))};}
static V v_mid(float r,float g,float b){return {((0.299f*r)+(0.114f*b))+(0.587f*g),((-0.147f*r)+(0.436f*b))-(0.289f*g),((0.615f*r)-(0.100f*b))-(0.515f*g)};}
static V v_bf (float r,float g,float b){return {((0.114f*b)+(0.587f*g))+(0.299f*r),((0.436f*b)-(0.147f*r))-(0.289f*g),((-0.100f*b)+(0.615f*r))-(0.515f*g)};}
static V v_fma(float r,float g,float b){return {fmaf(0.114f,b,fmaf(0.587f,g,0.299f*r)),fmaf(0.436f,b,fmaf(-0.289f,g,-0.147f*r)),fmaf(-0.100f,b,fmaf(-0.515f,g,0.615f*r))};}
static V v_fma1(float r,float g,float b){return {fmaf(0.114f,b,(0.299f*r)+(0.587f*g)),fmaf(0.436f,b,(-0.147f*r)-(0.289f*g)),fmaf(-0.100f,b,(0.615f*r)-(0.515f*g))};}
static V v_dbl(float r,float g,float b){double R=r,G=g,B=b;return {(float)(((0.299*R)+(0.587*G))+(0.114*B)),(float)(((-0.147*R)-(0.289*G))+(0.436*B)),(float)(((0.615*R)-(0.515*G))-(0.100*B))};}
typedef V(*FN)(float,float,float);
static FN fns[]={v_ltr,v_rtl,v_mid,v_bf,v_fma,v_fma1,v_dbl};
static const int NC=7;
static bool visdiff(float r,float g,float b){
  V res[NC]; for(int i=0;i<NC;i++) res[i]=fns[i](r,g,b);
  char a[64],c[64];
  for(int i=1;i<NC;i++){
    const float*p0=&res[0].y,*pi=&res[i].y;
    for(int k=0;k<3;k++){snprintf(a,64,"%.6g",(double)p0[k]);snprintf(c,64,"%.6g",(double)pi[k]);if(strcmp(a,c))return true;}
  }
  return false;
}
int main(int argc,char**argv){
  long N=atol(argv[1]); unsigned seed=atoi(argv[2]); int mode=atoi(argv[3]); // mode1: only visible-diff triples
  std::mt19937_64 rng(seed);
  long out=0; long tries=0;
  while(out<N && tries<N*4000){
    tries++;
    float t[3];
    int m=rng()%8;
    for(int k=0;k<3;k++){
      double x;
      switch(m){
        case 0: x=(double)(rng()%1000001)/1000000.0; break;             // [0,1]
        case 1: x=(double)(rng()%257)/256.0; break;                      // dyadic [0,1]
        case 2: x=ldexp((double)(rng()%(1u<<23))+(1u<<23),-23)*ldexp(1.0,(int)(rng()%40)-20); break;
        case 3: x=(double)(int64_t)(rng()%2000001)/1000.0-1000.0; break;
        case 4: x=(double)(int64_t)(rng()%2001)-1000.0; break;
        case 5: x=(double)(rng()%1000001)/1000000.0*(rng()%2?1:-1); break;
        case 6: { uint32_t u=(rng()%0x3F800000u)+0x30000000u; x=FB(u)*(rng()%2?1:-1); } break;
        default: x=(double)(rng()%1000001)/1000000.0; break;
      }
      t[k]=(float)x;
      if(!std::isfinite(t[k])||(t[k]!=0.0f&&fabsf(t[k])<1e-30f)) t[k]=0.5f;
    }
    if(mode==1 && !visdiff(t[0],t[1],t[2])) continue;
    printf("%.9g %.9g %.9g\n",t[0],t[1],t[2]);
    out++;
  }
  return 0;
}
